window.__finlexDocLoaded(74,{"id":74,"articles":[{"id":2313,"no":"第一条","heading":"","text":"在中华人民共和国境内，企业和其他取得收入的组织(以下统称企业)为企业所得税的纳税人，依照本法的规定缴纳企业所得税。 个人独资企业、合伙企业不适用本法。","seq":0,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":1,"target_art_no":"第二条","dir":"in","note":"实施条例细化：第二条解释企业所得税法第1条"},{"doc_id":117,"tier":"L3","score":64,"rel_kind":"cites","target_seq":5,"target_art_no":"第6节","dir":"in","note":"正文显式引用《中华人民共和国企业所得税法》"}]},{"id":2314,"no":"第二条","heading":"","text":"企业分为居民企业和非居民企业。 本法所称居民企业，是指依法在中国境内成立，或者依照外国(地区)法律成立但实际管理机构在中国境内的企业。 本法所称非居民企业，是指依照外国(地区)法律成立且实际管理机构不在中国境内，但在中国境内设立机构、场所的，或者在中国境内未设立机构、场所，但有来源于中国境内所得的企业。","seq":1,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":2,"target_art_no":"第三条","dir":"in","note":"实施条例细化：第三条解释企业所得税法第2条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":3,"target_art_no":"第四条","dir":"in","note":"实施条例细化：第四条解释企业所得税法第2条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":4,"target_art_no":"第五条","dir":"in","note":"实施条例细化：第五条解释企业所得税法第2条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":130,"target_art_no":"第一百三十一条","dir":"in","note":"实施条例细化：第一百三十一条解释企业所得税法第2条"}]},{"id":2315,"no":"第三条","heading":"","text":"居民企业应当就其来源于中国境内、境外的所得缴纳企业所得税。 非居民企业在中国境内设立机构、场所的，应当就其所设机构、场所取得的来源于中国境内的所得，以及发生在中国境外但与其所设机构、场所有实际联系的所得，缴纳企业所得税。 非居民企业在中国境内未设立机构、场所的，或者虽设立机构、场所但取得的所得与其所设机构、场所没有实际联系的，应当就其来源于中国境内的所得缴纳企业所得税。","seq":2,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":5,"target_art_no":"第六条","dir":"in","note":"实施条例细化：第六条解释企业所得税法第3条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":6,"target_art_no":"第七条","dir":"in","note":"实施条例细化：第七条解释企业所得税法第3条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":7,"target_art_no":"第八条","dir":"in","note":"实施条例细化：第八条解释企业所得税法第3条"}]},{"id":2316,"no":"第四条","heading":"","text":"企业所得税的税率为25%。 非居民企业取得本法第三条第三款规定的所得，适用税率为20%。","seq":3,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":117,"target_art_no":"第一百一十八条","dir":"in","note":"实施条例细化：第一百一十八条解释企业所得税法第4条"}]},{"id":2317,"no":"第五条","heading":"","text":"企业每一纳税年度的收入总额，减除不征税收入、免税收入、各项扣除以及允许弥补的以前年度亏损后的余额，为应纳税所得额。","seq":4,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":9,"target_art_no":"第十条","dir":"in","note":"实施条例细化：第十条解释企业所得税法第5条"},{"doc_id":18,"tier":"L4","score":58,"rel_kind":"cross_domain","target_seq":6,"target_art_no":"第七条","dir":"in","note":"税会条对条：资产负债账面价值与计税基础暂时性差异 ↔ 应纳税所得额"}]},{"id":2318,"no":"第六条","heading":"","text":"企业以货币形式和非货币形式从各种来源取得的收入，为收入总额。包括： (一)销售货物收入; (二)提供劳务收入; (三)转让财产收入; (四)股息、红利等权益性投资收益; (五)利息收入; (六)租金收入; (七)特许权使用费收入; (八)接受捐赠收入; (九)其他收入。","seq":5,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":11,"target_art_no":"第十二条","dir":"in","note":"实施条例细化：第十二条解释企业所得税法第6条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":12,"target_art_no":"第十三条","dir":"in","note":"实施条例细化：第十三条解释企业所得税法第6条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":13,"target_art_no":"第十四条","dir":"in","note":"实施条例细化：第十四条解释企业所得税法第6条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":14,"target_art_no":"第十五条","dir":"in","note":"实施条例细化：第十五条解释企业所得税法第6条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":15,"target_art_no":"第十六条","dir":"in","note":"实施条例细化：第十六条解释企业所得税法第6条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":16,"target_art_no":"第十七条","dir":"in","note":"实施条例细化：第十七条解释企业所得税法第6条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":17,"target_art_no":"第十八条","dir":"in","note":"实施条例细化：第十八条解释企业所得税法第6条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":18,"target_art_no":"第十九条","dir":"in","note":"实施条例细化：第十九条解释企业所得税法第6条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":19,"target_art_no":"第二十条","dir":"in","note":"实施条例细化：第二十条解释企业所得税法第6条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":20,"target_art_no":"第二十一条","dir":"in","note":"实施条例细化：第二十一条解释企业所得税法第6条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":21,"target_art_no":"第二十二条","dir":"in","note":"实施条例细化：第二十二条解释企业所得税法第6条"},{"doc_id":15,"tier":"L4","score":56,"rel_kind":"cross_domain","target_seq":3,"target_art_no":"第四条","dir":"in","note":"税会条对条：会计收入确认 ↔ 企业所得税收入总额口径"}]},{"id":2319,"no":"第七条","heading":"","text":"收入总额中的下列收入为不征税收入： (一)财政拨款; (二)依法收取并纳入财政管理的行政事业性收费、政府性基金; (三)国务院规定的其他不征税收入。","seq":6,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":25,"target_art_no":"第二十六条","dir":"in","note":"实施条例细化：第二十六条解释企业所得税法第7条"}]},{"id":2320,"no":"第八条","heading":"","text":"企业实际发生的与取得收入有关的、合理的支出，包括成本、费用、税金、损失和其他支出，准予在计算应纳税所得额时扣除。","seq":7,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":26,"target_art_no":"第二十七条","dir":"in","note":"实施条例细化：第二十七条解释企业所得税法第8条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":28,"target_art_no":"第二十九条","dir":"in","note":"实施条例细化：第二十九条解释企业所得税法第8条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":29,"target_art_no":"第三十条","dir":"in","note":"实施条例细化：第三十条解释企业所得税法第8条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":30,"target_art_no":"第三十一条","dir":"in","note":"实施条例细化：第三十一条解释企业所得税法第8条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":31,"target_art_no":"第三十二条","dir":"in","note":"实施条例细化：第三十二条解释企业所得税法第8条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":32,"target_art_no":"第三十三条","dir":"in","note":"实施条例细化：第三十三条解释企业所得税法第8条"}]},{"id":2321,"no":"第九条","heading":"","text":"企业发生的公益性捐赠支出，在年度利润总额12%以内的部分，准予在计算应纳税所得额时扣除;超过年度利润总额12%的部分，准予结转以后三年内在计算应纳税所得额时扣除。","seq":8,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":50,"target_art_no":"第五十一条","dir":"in","note":"实施条例细化：第五十一条解释企业所得税法第9条"}]},{"id":2322,"no":"第十条","heading":"","text":"在计算应纳税所得额时，下列支出不得扣除： (一)向投资者支付的股息、红利等权益性投资收益款项; (二)企业所得税税款; (三)税收滞纳金; (四)罚金、罚款和被没收财物的损失; (五)本法第九条规定以外的捐赠支出; (六)赞助支出; (七)未经核定的准备金支出; (八)与取得收入无关的其他支出。","seq":9,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":53,"target_art_no":"第五十四条","dir":"in","note":"实施条例细化：第五十四条解释企业所得税法第10条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":54,"target_art_no":"第五十五条","dir":"in","note":"实施条例细化：第五十五条解释企业所得税法第10条"}]},{"id":2323,"no":"第十一条","heading":"","text":"在计算应纳税所得额时，企业按照规定计算的固定资产折旧，准予扣除。 下列固定资产不得计算折旧扣除： (一)房屋、建筑物以外未投入使用的固定资产; (二)以经营租赁方式租入的固定资产; (三)以融资租赁方式租出的固定资产; (四)已足额提取折旧仍继续使用的固定资产; (五)与经营活动无关的固定资产; (六)单独估价作为固定资产入账的土地; (七)其他不得计算折旧扣除的固定资产。","seq":10,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":56,"target_art_no":"第五十七条","dir":"in","note":"实施条例细化：第五十七条解释企业所得税法第11条"},{"doc_id":5,"tier":"L4","score":56,"rel_kind":"cross_domain","target_seq":13,"target_art_no":"第十四条","dir":"in","note":"税会条对条：固定资产会计折旧 ↔ 企业所得税折旧税前扣除"}]},{"id":2324,"no":"第十二条","heading":"","text":"在计算应纳税所得额时，企业按照规定计算的无形资产摊销费用，准予扣除。 下列无形资产不得计算摊销费用扣除： (一)自行开发的支出已在计算应纳税所得额时扣除的无形资产; (二)自创商誉; (三)与经营活动无关的无形资产; (四)其他不得计算摊销费用扣除的无形资产。","seq":11,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":64,"target_art_no":"第六十五条","dir":"in","note":"实施条例细化：第六十五条解释企业所得税法第12条"}]},{"id":2325,"no":"第十三条","heading":"","text":"在计算应纳税所得额时，企业发生的下列支出作为长期待摊费用，按照规定摊销的，准予扣除： (一)已足额提取折旧的固定资产的改建支出; (二)租入固定资产的改建支出; (三)固定资产的大修理支出; (四)其他应当作为长期待摊费用的支出。","seq":12,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":57,"target_art_no":"第五十八条","dir":"in","note":"实施条例细化：第五十八条解释企业所得税法第13条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":67,"target_art_no":"第六十八条","dir":"in","note":"实施条例细化：第六十八条解释企业所得税法第13条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":68,"target_art_no":"第六十九条","dir":"in","note":"实施条例细化：第六十九条解释企业所得税法第13条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":69,"target_art_no":"第七十条","dir":"in","note":"实施条例细化：第七十条解释企业所得税法第13条"}]},{"id":2326,"no":"第十四条","heading":"","text":"企业对外投资期间，投资资产的成本在计算应纳税所得额时不得扣除。","seq":13,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":70,"target_art_no":"第七十一条","dir":"in","note":"实施条例细化：第七十一条解释企业所得税法第14条"}]},{"id":2327,"no":"第十五条","heading":"","text":"企业使用或者销售存货，按照规定计算的存货成本，准予在计算应纳税所得额时扣除。","seq":14,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":71,"target_art_no":"第七十二条","dir":"in","note":"实施条例细化：第七十二条解释企业所得税法第15条"}]},{"id":2328,"no":"第十六条","heading":"","text":"企业转让资产，该项资产的净值，准予在计算应纳税所得额时扣除。","seq":15,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":73,"target_art_no":"第七十四条","dir":"in","note":"实施条例细化：第七十四条解释企业所得税法第16条"}]},{"id":2329,"no":"第十七条","heading":"","text":"企业在汇总计算缴纳企业所得税时，其境外营业机构的亏损不得抵减境内营业机构的盈利。","seq":16},{"id":2330,"no":"第十八条","heading":"","text":"企业纳税年度发生的亏损，准予向以后年度结转，用以后年度的所得弥补，但结转年限最长不得超过五年。","seq":17},{"id":2331,"no":"第十九条","heading":"","text":"非居民企业取得本法第三条第三款规定的所得，按照下列方法计算其应纳税所得额： (一)股息、红利等权益性投资收益和利息、租金、特许权使用费所得，以收入全额为应纳税所得额; (二)转让财产所得，以收入全额减除财产净值后的余额为应纳税所得额; (三)其他所得，参照前两项规定的方法计算应纳税所得额。","seq":18,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":102,"target_art_no":"第一百零三条","dir":"in","note":"实施条例细化：第一百零三条解释企业所得税法第19条"}]},{"id":2332,"no":"第二十条","heading":"","text":"本章规定的收入、扣除的具体范围、标准和资产的税务处理的具体办法，由国务院财政、税务主管部门规定。","seq":19},{"id":2333,"no":"第二十一条","heading":"","text":"在计算应纳税所得额时，企业财务、会计处理办法与税收法律、行政法规的规定不一致的，应当依照税收法律、行政法规的规定计算。","seq":20},{"id":2334,"no":"第二十二条","heading":"","text":"企业的应纳税所得额乘以适用税率，减除依照本法关于税收优惠的规定减免和抵免的税额后的余额，为应纳税额。","seq":21,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":75,"target_art_no":"第七十六条","dir":"in","note":"实施条例细化：第七十六条解释企业所得税法第22条"}]},{"id":2335,"no":"第二十三条","heading":"","text":"企业取得的下列所得已在境外缴纳的所得税税额，可以从其当期应纳税额中抵免，抵免限额为该项所得依照本法规定计算的应纳税额;超过抵免限额的部分，可以在以后五个年度内，用每年度抵免限额抵免当年应抵税额后的余额进行抵补： (一)居民企业来源于中国境外的应税所得; (二)非居民企业在中国境内设立机构、场所，取得发生在中国境外但与该机构、场所有实际联系的应税所得。","seq":22,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":76,"target_art_no":"第七十七条","dir":"in","note":"实施条例细化：第七十七条解释企业所得税法第23条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":77,"target_art_no":"第七十八条","dir":"in","note":"实施条例细化：第七十八条解释企业所得税法第23条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":78,"target_art_no":"第七十九条","dir":"in","note":"实施条例细化：第七十九条解释企业所得税法第23条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":80,"target_art_no":"第八十一条","dir":"in","note":"实施条例细化：第八十一条解释企业所得税法第23条"}]},{"id":2336,"no":"第二十四条","heading":"","text":"居民企业从其直接或者间接控制的外国企业分得的来源于中国境外的股息、红利等权益性投资收益，外国企业在境外实际缴纳的所得税税额中属于该项所得负担的部分，可以作为该居民企业的可抵免境外所得税税额，在本法第二十三条规定的抵免限额内抵免。","seq":23,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":79,"target_art_no":"第八十条","dir":"in","note":"实施条例细化：第八十条解释企业所得税法第24条"}]},{"id":2337,"no":"第二十五条","heading":"","text":"国家对重点扶持和鼓励发展的产业和项目，给予企业所得税优惠。","seq":24},{"id":2338,"no":"第二十六条","heading":"","text":"企业的下列收入为免税收入： (一)国债利息收入; (二)符合条件的居民企业之间的股息、红利等权益性投资收益; (三)在中国境内设立机构、场所的非居民企业从居民企业取得与该机构、场所有实际联系的股息、红利等权益性投资收益; (四)符合条件的非营利组织的收入。","seq":25,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":81,"target_art_no":"第八十二条","dir":"in","note":"实施条例细化：第八十二条解释企业所得税法第26条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":82,"target_art_no":"第八十三条","dir":"in","note":"实施条例细化：第八十三条解释企业所得税法第26条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":83,"target_art_no":"第八十四条","dir":"in","note":"实施条例细化：第八十四条解释企业所得税法第26条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":84,"target_art_no":"第八十五条","dir":"in","note":"实施条例细化：第八十五条解释企业所得税法第26条"}]},{"id":2339,"no":"第二十七条","heading":"","text":"企业的下列所得，可以免征、减征企业所得税： (一)从事农、林、牧、渔业项目的所得; (二)从事国家重点扶持的公共基础设施项目投资经营的所得; (三)从事符合条件的环境保护、节能节水项目的所得; (四)符合条件的技术转让所得; (五)本法第三条第三款规定的所得。","seq":26,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":85,"target_art_no":"第八十六条","dir":"in","note":"实施条例细化：第八十六条解释企业所得税法第27条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":86,"target_art_no":"第八十七条","dir":"in","note":"实施条例细化：第八十七条解释企业所得税法第27条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":87,"target_art_no":"第八十八条","dir":"in","note":"实施条例细化：第八十八条解释企业所得税法第27条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":89,"target_art_no":"第九十条","dir":"in","note":"实施条例细化：第九十条解释企业所得税法第27条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":90,"target_art_no":"第九十一条","dir":"in","note":"实施条例细化：第九十一条解释企业所得税法第27条"}]},{"id":2340,"no":"第二十八条","heading":"","text":"符合条件的小型微利企业，减按20%的税率征收企业所得税。 国家需要重点扶持的高新技术企业，减按15%的税率征收企业所得税。","seq":27,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":91,"target_art_no":"第九十二条","dir":"in","note":"实施条例细化：第九十二条解释企业所得税法第28条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":92,"target_art_no":"第九十三条","dir":"in","note":"实施条例细化：第九十三条解释企业所得税法第28条"}]},{"id":2341,"no":"第二十九条","heading":"","text":"民族自治地方的自治机关对本民族自治地方的企业应缴纳的企业所得税中属于地方分享的部分，可以决定减征或者免征。自治州、自治县决定减征或者免征的，须报省、自治区、直辖市人民政府批准。","seq":28,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":93,"target_art_no":"第九十四条","dir":"in","note":"实施条例细化：第九十四条解释企业所得税法第29条"}]},{"id":2342,"no":"第三十条","heading":"","text":"企业的下列支出，可以在计算应纳税所得额时加计扣除： (一)开发新技术、新产品、新工艺发生的研究开发费用; (二)安置残疾人员及国家鼓励安置的其他就业人员所支付的工资。","seq":29,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":94,"target_art_no":"第九十五条","dir":"in","note":"实施条例细化：第九十五条解释企业所得税法第30条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":95,"target_art_no":"第九十六条","dir":"in","note":"实施条例细化：第九十六条解释企业所得税法第30条"},{"doc_id":7,"tier":"L4","score":56,"rel_kind":"cross_domain","target_seq":6,"target_art_no":"第七条","dir":"in","note":"税会条对条：内部研发研究/开发阶段划分 ↔ 研发费用加计扣除"}]},{"id":2343,"no":"第三十一条","heading":"","text":"创业投资企业从事国家需要重点扶持和鼓励的创业投资，可以按投资额的一定比例抵扣应纳税所得额。","seq":30,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":96,"target_art_no":"第九十七条","dir":"in","note":"实施条例细化：第九十七条解释企业所得税法第31条"}]},{"id":2344,"no":"第三十二条","heading":"","text":"企业的固定资产由于技术进步等原因，确需加速折旧的，可以缩短折旧年限或者采取加速折旧的方法。","seq":31,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":97,"target_art_no":"第九十八条","dir":"in","note":"实施条例细化：第九十八条解释企业所得税法第32条"}]},{"id":2345,"no":"第三十三条","heading":"","text":"企业综合利用资源，生产符合国家产业政策规定的产品所取得的收入，可以在计算应纳税所得额时减计收入。","seq":32,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":98,"target_art_no":"第九十九条","dir":"in","note":"实施条例细化：第九十九条解释企业所得税法第33条"}]},{"id":2346,"no":"第三十四条","heading":"","text":"企业购置用于环境保护、节能节水、安全生产等专用设备的投资额，可以按一定比例实行税额抵免。","seq":33,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":99,"target_art_no":"第一百条","dir":"in","note":"实施条例细化：第一百条解释企业所得税法第34条"}]},{"id":2347,"no":"第三十五条","heading":"","text":"本法规定的税收优惠的具体办法，由国务院规定。","seq":34},{"id":2348,"no":"第三十六条","heading":"","text":"根据国民经济和社会发展的需要，或者由于突发事件等原因对企业经营活动产生重大影响的，国务院可以制定企业所得税专项优惠政策，报全国人民代表大会常务委员会备案。","seq":35},{"id":2349,"no":"第三十七条","heading":"","text":"对非居民企业取得本法第三条第三款规定的所得应缴纳的所得税，实行源泉扣缴，以支付人为扣缴义务人。税款由扣缴义务人在每次支付或者到期应支付时，从支付或者到期应支付的款项中扣缴。","seq":36,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":103,"target_art_no":"第一百零四条","dir":"in","note":"实施条例细化：第一百零四条解释企业所得税法第37条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":104,"target_art_no":"第一百零五条","dir":"in","note":"实施条例细化：第一百零五条解释企业所得税法第37条"}]},{"id":2350,"no":"第三十八条","heading":"","text":"对非居民企业在中国境内取得工程作业和劳务所得应缴纳的所得税，税务机关可以指定工程价款或者劳务费的支付人为扣缴义务人。","seq":37,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":105,"target_art_no":"第一百零六条","dir":"in","note":"实施条例细化：第一百零六条解释企业所得税法第38条"}]},{"id":2351,"no":"第三十九条","heading":"","text":"依照本法第三十七条、第三十八条规定应当扣缴的所得税，扣缴义务人未依法扣缴或者无法履行扣缴义务的，由纳税人在所得发生地缴纳。纳税人未依法缴纳的，税务机关可以从该纳税人在中国境内其他收入项目的支付人应付的款项中，追缴该纳税人的应纳税款。","seq":38,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":106,"target_art_no":"第一百零七条","dir":"in","note":"实施条例细化：第一百零七条解释企业所得税法第39条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":107,"target_art_no":"第一百零八条","dir":"in","note":"实施条例细化：第一百零八条解释企业所得税法第39条"}]},{"id":2352,"no":"第四十条","heading":"","text":"扣缴义务人每次代扣的税款，应当自代扣之日起七日内缴入国库，并向所在地的税务机关报送扣缴企业所得税报告表。","seq":39},{"id":2353,"no":"第四十一条","heading":"","text":"企业与其关联方之间的业务往来，不符合独立交易原则而减少企业或者其关联方应纳税收入或者所得额的，税务机关有权按照合理方法调整。 企业与其关联方共同开发、受让无形资产，或者共同提供、接受劳务发生的成本，在计算应纳税所得额时应当按照独立交易原则进行分摊。","seq":40,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":108,"target_art_no":"第一百零九条","dir":"in","note":"实施条例细化：第一百零九条解释企业所得税法第41条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":109,"target_art_no":"第一百一十条","dir":"in","note":"实施条例细化：第一百一十条解释企业所得税法第41条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":110,"target_art_no":"第一百一十一条","dir":"in","note":"实施条例细化：第一百一十一条解释企业所得税法第41条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":111,"target_art_no":"第一百一十二条","dir":"in","note":"实施条例细化：第一百一十二条解释企业所得税法第41条"}]},{"id":2354,"no":"第四十二条","heading":"","text":"企业可以向税务机关提出与其关联方之间业务往来的定价原则和计算方法，税务机关与企业协商、确认后，达成预约定价安排。","seq":41,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":112,"target_art_no":"第一百一十三条","dir":"in","note":"实施条例细化：第一百一十三条解释企业所得税法第42条"}]},{"id":2355,"no":"第四十三条","heading":"","text":"企业向税务机关报送年度企业所得税纳税申报表时，应当就其与关联方之间的业务往来，附送年度关联业务往来报告表。 税务机关在进行关联业务调查时，企业及其关联方，以及与关联业务调查有关的其他企业，应当按照规定提供相关资料。","seq":42,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":113,"target_art_no":"第一百一十四条","dir":"in","note":"实施条例细化：第一百一十四条解释企业所得税法第43条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":121,"target_art_no":"第一百二十二条","dir":"in","note":"实施条例细化：第一百二十二条解释企业所得税法第43条"}]},{"id":2356,"no":"第四十四条","heading":"","text":"企业不提供与其关联方之间业务往来资料，或者提供虚假、不完整资料，未能真实反映其关联业务往来情况的，税务机关有权依法核定其应纳税所得额。","seq":43,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":114,"target_art_no":"第一百一十五条","dir":"in","note":"实施条例细化：第一百一十五条解释企业所得税法第44条"}]},{"id":2357,"no":"第四十五条","heading":"","text":"由居民企业，或者由居民企业和中国居民控制的设立在实际税负明显低于本法第四条第一款规定税率水平的国家(地区)的企业，并非由于合理的经营需要而对利润不作分配或者减少分配的，上述利润中应归属于该居民企业的部分，应当计入该居民企业的当期收入。","seq":44,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":115,"target_art_no":"第一百一十六条","dir":"in","note":"实施条例细化：第一百一十六条解释企业所得税法第45条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":116,"target_art_no":"第一百一十七条","dir":"in","note":"实施条例细化：第一百一十七条解释企业所得税法第45条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":117,"target_art_no":"第一百一十八条","dir":"in","note":"实施条例细化：第一百一十八条解释企业所得税法第45条"}]},{"id":2358,"no":"第四十六条","heading":"","text":"企业从其关联方接受的债权性投资与权益性投资的比例超过规定标准而发生的利息支出，不得在计算应纳税所得额时扣除。","seq":45,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":118,"target_art_no":"第一百一十九条","dir":"in","note":"实施条例细化：第一百一十九条解释企业所得税法第46条"}]},{"id":2359,"no":"第四十七条","heading":"","text":"企业实施其他不具有合理商业目的的安排而减少其应纳税收入或者所得额的，税务机关有权按照合理方法调整。","seq":46,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":119,"target_art_no":"第一百二十条","dir":"in","note":"实施条例细化：第一百二十条解释企业所得税法第47条"}]},{"id":2360,"no":"第四十八条","heading":"","text":"税务机关依照本章规定作出纳税调整，需要补征税款的，应当补征税款，并按照国务院规定加收利息。","seq":47,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":121,"target_art_no":"第一百二十二条","dir":"in","note":"实施条例细化：第一百二十二条解释企业所得税法第48条"}]},{"id":2361,"no":"第四十九条","heading":"","text":"企业所得税的征收管理除本法规定外，依照《中华人民共和国税收征收管理法》的规定执行。","seq":48,"links":[{"doc_id":76,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中华人民共和国税收征收管理法》"}]},{"id":2362,"no":"第五十条","heading":"","text":"除税收法律、行政法规另有规定外，居民企业以企业登记注册地为纳税地点;但登记注册地在境外的，以实际管理机构所在地为纳税地点。 居民企业在中国境内设立不具有法人资格的营业机构的，应当汇总计算并缴纳企业所得税。","seq":49,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":123,"target_art_no":"第一百二十四条","dir":"in","note":"实施条例细化：第一百二十四条解释企业所得税法第50条"},{"doc_id":85,"tier":"L5","score":40,"rel_kind":"explains","target_seq":2,"target_art_no":"第三项","dir":"in","note":"官方解读对应《中华人民共和国企业所得税法》第50条"}]},{"id":2363,"no":"第五十一条","heading":"","text":"非居民企业取得本法第三条第二款规定的所得，以机构、场所所在地为纳税地点。非居民企业在中国境内设立两个或者两个以上机构、场所，符合国务院税务主管部门规定条件的，可以选择由其主要机构、场所汇总缴纳企业所得税。 非居民企业取得本法第三条第三款规定的所得，以扣缴义务人所在地为纳税地点。","seq":50,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":125,"target_art_no":"第一百二十六条","dir":"in","note":"实施条例细化：第一百二十六条解释企业所得税法第51条"}]},{"id":2364,"no":"第五十二条","heading":"","text":"除国务院另有规定外，企业之间不得合并缴纳企业所得税。","seq":51},{"id":2365,"no":"第五十三条","heading":"","text":"企业所得税按纳税年度计算。纳税年度自公历1月1日起至12月31日止。 企业在一个纳税年度中间开业，或者终止经营活动，使该纳税年度的实际经营期不足十二个月的，应当以其实际经营期为一个纳税年度。 企业依法清算时，应当以清算期间作为一个纳税年度。","seq":52},{"id":2366,"no":"第五十四条","heading":"","text":"企业所得税分月或者分季预缴。 企业应当自月份或者季度终了之日起十五日内，向税务机关报送预缴企业所得税纳税申报表，预缴税款。 企业应当自年度终了之日起五个月内，向税务机关报送年度企业所得税纳税申报表，并汇算清缴，结清应缴应退税款。 企业在报送企业所得税纳税申报表时，应当按照规定附送财务会计报告和其他有关资料。","seq":53,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":126,"target_art_no":"第一百二十七条","dir":"in","note":"实施条例细化：第一百二十七条解释企业所得税法第54条"},{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":127,"target_art_no":"第一百二十八条","dir":"in","note":"实施条例细化：第一百二十八条解释企业所得税法第54条"}]},{"id":2367,"no":"第五十五条","heading":"","text":"企业在年度中间终止经营活动的，应当自实际经营终止之日起六十日内，向税务机关办理当期企业所得税汇算清缴。 企业应当在办理注销登记前，就其清算所得向税务机关申报并依法缴纳企业所得税。","seq":54,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":10,"target_art_no":"第十一条","dir":"in","note":"实施条例细化：第十一条解释企业所得税法第55条"}]},{"id":2368,"no":"第五十六条","heading":"","text":"依照本法缴纳的企业所得税，以人民币计算。所得以人民币以外的货币计算的，应当折合成人民币计算并缴纳税款。","seq":55},{"id":2369,"no":"第五十七条","heading":"","text":"本法公布前已经批准设立的企业，依照当时的税收法律、行政法规规定，享受低税率优惠的，按照国务院规定，可以在本法施行后五年内，逐步过渡到本法规定的税率;享受定期减免税优惠的，按照国务院规定，可以在本法施行后继续享受到期满为止，但因未获利而尚未享受优惠的，优惠期限从本法施行年度起计算。 法律设置的发展对外经济合作和技术交流的特定地区内，以及国务院已规定执行上述地区特殊政策的地区内新设立的国家需要重点扶持的高新技术企业，可以享受过渡性税收优惠，具体办法由国务院规定。 国家已确定的其他鼓励类企业，可以按照国务院规定享受减免税优惠。","seq":56,"links":[{"doc_id":78,"tier":"L1","score":96,"rel_kind":"companion","target_seq":129,"target_art_no":"第一百三十条","dir":"in","note":"实施条例细化：第一百三十条解释企业所得税法第57条"}]},{"id":2370,"no":"第五十八条","heading":"","text":"中华人民共和国政府同外国政府订立的有关税收的协定与本法有不同规定的，依照协定的规定办理。","seq":57},{"id":2371,"no":"第五十九条","heading":"","text":"国务院根据本法制定实施条例。","seq":58},{"id":2372,"no":"第六十条","heading":"","text":"本法自2008年1月1日起施行。1991年4月9日第七届全国人民代表大会第四次会议通过的《中华人民共和国外商投资企业和外国企业所得税法》和1993年12月13日国务院发布的《中华人民共和国企业所得税暂行条例》同时废止。 国家税务总局：https://fgk.chinatax.gov.cn/zcfgk/c100009/c5193018/content.html 相关图解： 1.一图了解居民企业技术转让所得减免企业所得税优惠政策 https://hainan.chinatax.gov.cn/xxgk_6_8/29154072.html 2..@小型微利企业，这些企业所得税优惠政策相关知识要了解↓ https://hainan.chinatax.gov.cn/xxgk_6_8/09157493.html 3.合规视界|处置废旧物、下脚料、残次品的收入别忘了缴税! https://hainan.chinatax.gov.cn/xxgk_6_8/04160879.html 4.注意!这些支出不得在企业所得税税前扣除 https://hainan.chinatax.gov.cn/xxgk_6_8/15161109.html 5.快码住!农、林、牧、渔业企业所得税税惠礼包来了 https://hainan.chinatax.gov.cn/xxgk_6_8/24161209.html 6.琼小智讲税|关于小型微利企业减免，这些知识点快来收藏! https://hainan.chinatax.gov.cn/xxgk_6_8/16161528.html 7.@高新技术企业，这份税收政策“干货”请收好! https://hainan.chinatax.gov.cn/xxgk_6_8/16162480.html 8.琼小智讲税|不予返还的质保金未确认收入，违规啦! https://hainan.chinatax.gov.cn/xxgk_6_8/30164328.html 9.税法小课堂：非居民企业应该在哪儿缴纳企业所得税? https://hainan.chinatax.gov.cn/ssxc_5_5/05165434.html 10.合规经营|别拿“白条”不当回事!常见易错情形+合规指南一图讲清 https://hainan.chinatax.gov.cn/xxgk_6_8/22166137.html 11.合规经营|注意!企业申报纳税的五个易错点! https://hainan.chinatax.gov.cn/xxgk_6_8/04166376.html 12.合规经营|罚款到底能不能税前扣除? https://hainan.chinatax.gov.cn/xxgk_6_8/11166482.html 13.税法便利贴：一起了解企业所得税基础知识 https://hainan.chinatax.gov.cn/xxgk_6_8/10167044.html 相关视频： 1.税费政策我来讲|高新技术企业能享受哪些企业所得税优惠? https://hainan.chinatax.gov.cn/ssxc_5_5/29157702.html 2.税法小课堂：哪些收入要征收企业所得税? https://hainan.chinatax.gov.cn/ssxc_5_5/10161450.html 3.税法小课堂：哪些收入不征收企业所得税? https://hainan.chinatax.gov.cn/ssxc_5_5/16161525.html 4.税法小课堂丨企业生产经营中哪些支出可以税前扣除 https://hainan.chinatax.gov.cn/ssxc_5_5/23161609.html 5.税法小课堂：企业生产经营中哪些支出不能税前扣除? https://hainan.chinatax.gov.cn/ssxc_5_5/10161873.html 6.税法小课堂：企业发生的公益性捐赠支出如何税前扣除? https://hainan.chinatax.gov.cn/ssxc_5_5/21162088.html 7.税法小课堂：固定资产折旧如何税前扣除? https://hainan.chinatax.gov.cn/ssxc_5_5/04162354.html 8.税法小课堂：哪些所得可以免征、减征企业所得税？ https://hainan.chinatax.gov.cn/ssxc_5_5/27163167.html 9.税法小课堂：存货成本如何在企业所得税税前扣除? https://hainan.chinatax.gov.cn/ssxc_5_5/09164996.html 10.税法小课堂：居民企业应该在哪儿缴纳企业所得税? https://hainan.chinatax.gov.cn/ssxc_5_5/28165325.html 11.税法小课堂：企业应在何时缴纳企业所得税？ https://hainan.chinatax.gov.cn/ssxc_5_5/10165471.html 12.税法小课堂：企业在年度中间注销，企业所得税该如何处理？ https://hainan.chinatax.gov.cn/ssxc_5_5/24165669.html","seq":59}]});
